const val=(v,ok,soon,late)=>{const t=today();return !v?'—':v<t?late:v<=addDay(t,30)?soon:ok};
const lvl=r=>{const p=parseInt(r.prob)||0,g=parseInt(r.grav)||0,n=p*g;return{n,t:!n?'—':n>=15?'Muito alto':n>=10?'Alto':n>=5?'Médio':'Baixo'}};
CALC.qsadoc=r=>({situacao:r.estado==='Obsoleto'?'—':val(r.proxRevisao,'Em dia','Rever em 30 dias','Por rever')});
CALC.qsaleg=r=>({situacao:val(r.validade,'Válido','Expira em 30 dias','Expirado')});
CALC.qsaemm=r=>({situacao:val(r.validade,'Válido','Expira em 30 dias','Expirado')});
CALC.qsaemerg=r=>({situacao:val(r.validade,'Válido','Expira em 30 dias','Expirado')});
CALC.qsanc=r=>({situacao:r.estado==='Fechada'?'Fechada':!r.prazo?'—':r.prazo<today()?'Em atraso':'Dentro do prazo'});
CALC.qsapt=r=>({situacao:['Encerrada','Recusada'].includes(r.estado)?'—':!r.validade?'—':r.validade<today()?'Expirada':'Válido'});
